#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float2 amzp_center;
uniform float amzp_directionDeg;
uniform float amzp_shape;
uniform float amzp_edgeThickness;
uniform float amzp_edgeIntensity;
uniform float amzp_widthPx;
uniform float amzp_sweepIntensity;
layout(color) uniform half4 amzp_lightColor;
uniform float amzp_lightReception;
uniform float amzp_rimWidthPx;
uniform float amzp_rimIntensity;
layout(color) uniform half4 amzp_rimColor;
uniform float amzp_rimReception;
uniform float amzp_rimAngleDeg;
uniform float amzp_innerWidthPx;
uniform float amzp_innerIntensity;
layout(color) uniform half4 amzp_innerColor;
uniform float amzp_innerReception;
uniform float amzp_alpha;




    const float PI = 3.141592653589793;

    void amzRender(){
      float2 uv = amzScreenNorm();
      float4 src = amzTexture(0, uv);


      float2 texel = 1.0 / getTexSize((screen.zw/1.0));


      float a_t = amzTexture(0, uv + float2(0.0,  texel.y)).a;
      float a_b = amzTexture(0, uv + float2(0.0, -texel.y)).a;
      float a_r = amzTexture(0, uv + float2( texel.x, 0.0)).a;
      float a_l = amzTexture(0, uv + float2(-texel.x, 0.0)).a;
      float2 grad = float2(a_r - a_l, a_t - a_b);
      float edgeStrength = length(grad);


      float bevelAngle = radians(135.0);
      float2 lightDir = normalize(float2(cos(bevelAngle), sin(bevelAngle)));
      float lighting = dot(normalize(grad + 1e-6), lightDir);


      float thickness = amzp_edgeThickness * 0.01; 
      float bevelMask = smoothstep(0.0, thickness + 1e-6, edgeStrength);

      float softness = 0.5;
      float powExp = 1.0 + (1.0 - softness) * 4.0;
      float highlight = pow(max(0.0,  lighting), powExp);
      float shadow    = pow(max(0.0, -lighting), powExp);

      float edgeGain = amzp_edgeIntensity / 100.0;
      float3 beveled = src.rgb;
      beveled = mix(beveled, float3(1.0), highlight * bevelMask * edgeGain);
      beveled = mix(beveled, float3(0.0), shadow    * bevelMask * edgeGain);


      float2 centerPx = amzp_center; 
      float2 centerUV = centerPx / screen.zw; 
      float2 p = uv - centerUV;

      p.x *= screen.zw.x / max(screen.zw.y, 1.0);
      float ang = radians(amzp_directionDeg);
      float2 dir = float2(cos(ang), sin(ang));
      float2 nrm = float2(-dir.y, dir.x);

      float width = amzp_widthPx / max(screen.zw.y, 1.0); 
      float d = abs(dot(p, nrm));


      float beam = pow(1.0 - smoothstep(0.0, width, d), 8.0);
      float glow = (1.0 - smoothstep(0.0, width * 5.0, d)) * 0.4;
      float sweep = (beam + glow) * (amzp_sweepIntensity / 25.0);


      sweep += bevelMask * beam * 2.0;


      float3 sweepCol = amzp_lightColor.rgb * sweep;
      float3 outRGB;
      if(int(int(amzp_lightReception))==0){

        outRGB = beveled + sweepCol;
      } else {

        outRGB = 1.0 - (1.0 - beveled) * (1.0 - sweepCol);
      }


      float2 n = normalize(grad + 1e-6);
      float rimWidth = amzp_rimWidthPx / max(screen.zw.y, 1.0);
      float rang = radians(amzp_rimAngleDeg);
      float2 rn = float2(cos(rang) * n.x - sin(rang) * n.y, sin(rang) * n.x + cos(rang) * n.y);
      float a_in_rim = amzTexture(0, uv - rn * rimWidth).a;
      float rimBand = clamp(src.a - a_in_rim, 0.0, 1.0);

      rimBand = smoothstep(0.0, 0.6, rimBand);
      float3 rimCol = amzp_rimColor.rgb * rimBand * (amzp_rimIntensity / 100.0);
      if(int(int(amzp_rimReception))==0){
        outRGB += rimCol;
      } else {
        outRGB = 1.0 - (1.0 - outRGB) * (1.0 - rimCol);
      }


      float innerWidth = amzp_innerWidthPx / max(screen.zw.y, 1.0);
      float a_in_inner = amzTexture(0, uv - n * innerWidth).a;
      float innerBand = clamp(src.a - a_in_inner, 0.0, 1.0);

      innerBand = 1.0 - exp(-innerBand * 3.0);
      float3 innerCol = amzp_innerColor.rgb * innerBand * (amzp_innerIntensity / 100.0);
      if(int(int(amzp_innerReception))==0){
        outRGB += innerCol;
      } else {
        outRGB = 1.0 - (1.0 - outRGB) * (1.0 - innerCol);
      }

      float aOut = src.a * amzp_alpha;
      amzOutput = float4(outRGB, 1.0) * aOut;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

